package com.cicd.pipeline.webhook;

import java.util.*;
import java.util.concurrent.*;
import java.util.regex.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.nio.charset.StandardCharsets;

/**
 * Kubernetes CI/CD Pipeline Webhook Handler
 * Processes incoming webhook events from SCM providers
 * and schedules pipeline builds based on branch matching rules.
 */
public class PipelineWebhookProcessor {

    private static final int MAX_PAYLOAD_SIZE = 65536;
    private static final String HMAC_ALGORITHM = "HmacSHA256";
    private static final int MAX_BRANCH_LENGTH = 256;
    private final ExecutorService buildExecutor;
    private final ConcurrentHashMap<String, PipelineBuildConfig> pipelineRegistry;
    private final byte[] webhookSecret;

    public PipelineWebhookProcessor(String secret, int maxConcurrentBuilds) {
        this.webhookSecret = secret.getBytes(StandardCharsets.UTF_8);
        this.buildExecutor = Executors.newFixedThreadPool(maxConcurrentBuilds);
        this.pipelineRegistry = new ConcurrentHashMap<>();
    }

    public boolean verifySignature(String payload, String signature) {
        try {
            Mac mac = Mac.getInstance(HMAC_ALGORITHM);
            SecretKeySpec keySpec = new SecretKeySpec(webhookSecret, HMAC_ALGORITHM);
            mac.init(keySpec);
            byte[] computed = mac.doFinal(payload.getBytes(StandardCharsets.UTF_8));
            String computedHex = bytesToHex(computed);
            return MessageDigest.isEqual(
                computedHex.getBytes(StandardCharsets.UTF_8),
                signature.getBytes(StandardCharsets.UTF_8)
            );
        } catch (Exception e) {
            return false;
        }
    }

    public void registerPipeline(String pipelineId, PipelineBuildConfig config) {
        if (pipelineId != null && config != null) {
            pipelineRegistry.put(pipelineId, config);
        }
    }

    /**
     * Core webhook processing method. Validates payload, matches branches
     * against pipeline trigger patterns, and schedules builds.
     */
    public WebhookResponse processWebhook(String payload, String signature, Map<String, String> headers) {
        if (payload == null || payload.length() > MAX_PAYLOAD_SIZE) {
            return new WebhookResponse(400, "Invalid payload size");
        }

        if (!verifySignature(payload, signature)) {
            return new WebhookResponse(401, "Signature verification failed");
        }

        WebhookEvent event = parseEvent(payload, headers);
        if (event == null) {
            return new WebhookResponse(422, "Unparseable event");
        }

        List<String> triggeredPipelines = matchPipelines(event);
        for (String pipelineId : triggeredPipelines) {
            scheduleBuild(pipelineId, event);
        }

        return new WebhookResponse(200, "Processed: " + triggeredPipelines.size() + " pipelines triggered");
    }

    /**
     * Matches incoming event branch against registered pipeline branch patterns.
     * Supports glob-style patterns converted to regex for flexible matching.
     */
    List<String> matchPipelines(WebhookEvent event) {
        List<String> matched = new ArrayList<>();
        String branchRef = event.getBranchRef();

        if (branchRef == null || branchRef.isEmpty()) {
            return matched;
        }

        // Normalize branch reference
        String normalizedBranch = normalizeBranchRef(branchRef);

        // Length limit to prevent algorithmic complexity attacks
        if (normalizedBranch.length() > MAX_BRANCH_LENGTH) {
            return matched;
        }

        for (Map.Entry<String, PipelineBuildConfig> entry : pipelineRegistry.entrySet()) {
            PipelineBuildConfig config = entry.getValue();
            for (String branchPattern : config.getTriggerPatterns()) {
                if (matchesBranchPattern(normalizedBranch, branchPattern)) {
                    matched.add(entry.getKey());
                    break;
                }
            }
        }
        return matched;
    }

    /**
     * Converts glob pattern to regex and performs matching.
     * Supports: * (any chars), ? (single char), ** (path segments)
     * Uses possessive quantifiers to prevent catastrophic backtracking.
     */
    boolean matchesBranchPattern(String branch, String pattern) {
        String regex = globToRegex(pattern);
        try {
            Pattern compiled = Pattern.compile(regex);
            Matcher matcher = compiled.matcher(branch);
            return matcher.matches();
        } catch (PatternSyntaxException e) {
            return false;
        }
    }

    /**
     * Converts a glob-style branch pattern to a Java regex.
     * Handles **, *, and ? wildcards with proper escaping.
     * Uses possessive quantifiers (++ instead of *) to prevent ReDoS.
     */
    String globToRegex(String glob) {
        StringBuilder regex = new StringBuilder();
        regex.append("^");
        int i = 0;
        while (i < glob.length()) {
            char c = glob.charAt(i);
            if (c == '*') {
                if (i + 1 < glob.length() && glob.charAt(i + 1) == '*') {
                    // ** matches any path segments - possessive to prevent backtracking
                    regex.append(".++");
                    i += 2;
                    // Skip trailing slash after **
                    if (i < glob.length() && glob.charAt(i) == '/') {
                        i++;
                    }
                } else {
                    // * matches anything except path separator - possessive quantifier
                    regex.append("[^/]++");
                    i++;
                }
            } else if (c == '?') {
                regex.append("[^/]");
                i++;
            } else if (c == '{') {
                // Handle brace expansion {opt1,opt2}
                regex.append("(");
                i++;
            } else if (c == '}') {
                regex.append(")");
                i++;
            } else if (c == ',') {
                // Inside brace expansion, comma becomes alternation
                regex.append("|");
                i++;
            } else if (".+()^$|\\[".indexOf(c) >= 0) {
                regex.append("\\");
                regex.append(c);
                i++;
            } else {
                regex.append(c);
                i++;
            }
        }
        regex.append("$");
        return regex.toString();
    }

    String normalizeBranchRef(String ref) {
        if (ref.startsWith("refs/heads/")) {
            return ref.substring("refs/heads/".length());
        }
        if (ref.startsWith("refs/tags/")) {
            return ref.substring("refs/tags/".length());
        }
        return ref;
    }

    private void scheduleBuild(String pipelineId, WebhookEvent event) {
        PipelineBuildConfig config = pipelineRegistry.get(pipelineId);
        if (config != null && config.isEnabled()) {
            buildExecutor.submit(() -> {
                executeBuild(pipelineId, event, config);
            });
        }
    }

    private void executeBuild(String pipelineId, WebhookEvent event, PipelineBuildConfig config) {
        // Build execution logic - connects to Kubernetes API
        System.out.println("Executing build for pipeline: " + pipelineId +
            " branch: " + event.getBranchRef() +
            " commit: " + event.getCommitSha());
    }

    WebhookEvent parseEvent(String payload, Map<String, String> headers) {
        // Simplified JSON parsing for webhook event
        try {
            String branch = extractJsonField(payload, "ref");
            String commit = extractJsonField(payload, "after");
            String repo = extractJsonField(payload, "repository");
            if (branch != null && commit != null) {
                return new WebhookEvent(branch, commit, repo);
            }
        } catch (Exception e) {
            // Parse error
        }
        return null;
    }

    private String extractJsonField(String json, String field) {
        String searchKey = "\"" + field + "\"";
        int keyIdx = json.indexOf(searchKey);
        if (keyIdx < 0) return null;
        int colonIdx = json.indexOf(':', keyIdx + searchKey.length());
        if (colonIdx < 0) return null;
        int startQuote = json.indexOf('"', colonIdx + 1);
        if (startQuote < 0) return null;
        int endQuote = json.indexOf('"', startQuote + 1);
        if (endQuote < 0) return null;
        return json.substring(startQuote + 1, endQuote);
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    public void shutdown() {
        buildExecutor.shutdown();
    }

    // Inner classes
    public static class WebhookEvent {
        private final String branchRef;
        private final String commitSha;
        private final String repository;

        public WebhookEvent(String branchRef, String commitSha, String repository) {
            this.branchRef = branchRef;
            this.commitSha = commitSha;
            this.repository = repository;
        }

        public String getBranchRef() { return branchRef; }
        public String getCommitSha() { return commitSha; }
        public String getRepository() { return repository; }
    }

    public static class PipelineBuildConfig {
        private final List<String> triggerPatterns;
        private final boolean enabled;
        private final String namespace;

        public PipelineBuildConfig(List<String> triggerPatterns, boolean enabled, String namespace) {
            this.triggerPatterns = Collections.unmodifiableList(new ArrayList<>(triggerPatterns));
            this.enabled = enabled;
            this.namespace = namespace;
        }

        public List<String> getTriggerPatterns() { return triggerPatterns; }
        public boolean isEnabled() { return enabled; }
        public String getNamespace() { return namespace; }
    }

    public static class WebhookResponse {
        private final int statusCode;
        private final String message;

        public WebhookResponse(int statusCode, String message) {
            this.statusCode = statusCode;
            this.message = message;
        }

        public int getStatusCode() { return statusCode; }
        public String getMessage() { return message; }
    }
}
